package com.glassbox.uml.core; import com.glassbox.uml.meta.UmlStereotype; import java.lang.reflect.*; import java.util.*;
public final class ClassModelBuilder{private ClassModelBuilder(){}public static UmlClassMeta build(Class<?> c,Object instance){String st=c.isAnnotationPresent(UmlStereotype.class)?c.getAnnotation(UmlStereotype.class).value():"";List<String>a=new ArrayList<>(),m=new ArrayList<>(),am=new ArrayList<>();Set<Class<?>>d=new HashSet<>();for(Field f:c.getDeclaredFields()){if(Modifier.isStatic(f.getModifiers()))continue;String v="";if(instance!=null)try{f.setAccessible(true);Object x=f.get(instance);v=" = "+String.valueOf(x);}catch(Exception ignored){}a.add("- "+f.getName()+": "+f.getType().getSimpleName()+v);if(f.getType().getPackageName().startsWith("com.glassbox"))d.add(f.getType());}for(Method x:c.getDeclaredMethods()){if(Modifier.isPrivate(x.getModifiers()))continue;String sig="+ "+x.getName()+"(): "+x.getReturnType().getSimpleName();(Modifier.isAbstract(x.getModifiers())?am:m).add(sig);}return new UmlClassMeta(c,c.getSimpleName(),st,Modifier.isAbstract(c.getModifiers()),c.isInterface(),a,m,am,c.getSuperclass(),c.getInterfaces(),d);}}
